import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const oldNames={recordingPreview:'liveRecordingPreviewAsync',recordingApply:'liveRecordingApplyAsync',undo:'liveUndoAsync',realtimePreview:'liveRealtimeArmPreviewAsync',realtimeApply:'liveRealtimeArmApplyAsync',disarm:'liveRealtimeDisarmAsync',stats:'liveRealtimeStatsAsync'};
function clean(v){v=JSON.parse(JSON.stringify(v));function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(dialog_)/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v;}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function change(root,path,value,remove=false){let at=root;for(const key of path.slice(0,-1))at=at[key];if(remove)delete at[path.at(-1)];else at[path.at(-1)]=structuredClone(value);}
function setup(config={}){
 const sim=new DeterministicLiveSimulator();const other=structuredClone(sim.state.tracks[0]);Object.assign(other,{ref:'track:other',name:'Other',objectIdentity:'simulator:track:other',devices:[],clips:[],clipSlots:[]});for(const key of ['volumeRef','panRef','cueRef','volumeIdentity','panIdentity','cueIdentity'])other.mixer[key]=null;other.mixer.sendRefs=[];other.mixer.sendIdentities=[];other.mixer.sends=[];sim.state.tracks.push(other);sim.state.tracks.forEach(t=>t.armed=true);sim.state.dialogRead=config.readOverride===undefined?{buttonCount:2,message:"Save changes before closing?",openDialogCount:1,done:true}:config.readOverride;for(const p of config.patches??[])change(sim.state,p.path,p.value,p.remove);
 const calls=[],cache=new Map(),overrides={provenance:'real-live',registryHash:'a'.repeat(64),...config.status};let fault='',fired=false,armed=false,pending,controller;
 const status=()=>({...sim.status(),...overrides,operations:overrides.operations??[...sim.status().operations,'realtime.arm','realtime.disarm','realtime.stats']});
 function once(){if(fired)return false;fired=true;return true;}
 async function invoke(i,c){const write=i.args.action!=='read';calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(write&&c?.transactionId&&cache.has(key))return cache.get(key);
 if(write&&['before','cancel','refusal'].includes(fault)&&once())throw fault==='refusal'?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault==='cancel'?'operation cancelled before dispatch':'injected operation failure');
 if(fault==='during-invoke')controller?.abort();if(write&&fault==='no-effect'&&once())return {changed:true};
 if(!write&&fault==='dialog-read'&&once())throw Error('injected dialog read failure');let result;if(!write)result=structuredClone(sim.state.dialogRead);else if(i.operation==='realtime.arm'){armed=true;await new Promise(r=>setTimeout(r,1));result={host:'127.0.0.1',port:9766,token:'t'.repeat(32),expiresAt:Date.now()+i.args.ttlMs,channels:i.args.channels,parameterRefs:i.args.parameterRefs,packetLimitBytes:512,ratePerSecond:64,burst:16};if(config.endpoint)Object.assign(result,config.endpoint);}else if(i.operation==='realtime.disarm'){armed=false;result={armed:false};}else if(i.operation==='realtime.stats')result={armed,accepted:2,pending:0};else {if(fault==='delayed'&&!fired)pending=structuredClone(sim.state.playback);result=sim.invoke(i);}
 if(write&&fault==='null'&&once())result=null;if(write&&fault==='false'&&once())result={recording:'yes',armed:'no'};if(write&&fault==='no-effect'&&once()){sim.state.playback.transport.sessionRecord=false;sim.state.playback.transport.arrangementRecord=false;}
 if(config.ack&&result&&typeof result==='object')Object.assign(result,config.ack);if(write&&c?.transactionId)cache.set(key,result);if(write&&fault==='after'&&once())throw Error('injected operation failure');return result;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));if(fault==='read'&&once())throw Error('injected authoritative read failure');if(pending){const v=sim.snapshot();v.playback=pending;pending=undefined;fired=true;return v;}return sim.snapshotAsync(c,r);},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));if(r.kind==='session-playback'&&fault==='playback-read'&&once())throw Error('injected authoritative read failure');const result=await sim.discoverAsync(r,c);if(r.kind==='session-playback'&&pending){result.items=[pending];pending=undefined;fired=true;}return result},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));return sim.get(r)},invokeAsync:invoke,refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));if(fault==='status'&&once())throw Error('injected status failure');if(fault==='during-status')controller?.abort();return status();}};
 return {host:new McpHost(adapter),sim,calls,overrides,get armed(){return armed},set fault(v){fault=v;fired=false},set controller(v){controller=v}};
}

const names={dialogPreview:'liveApplicationDialogPreviewAsync',dialogApply:'liveApplicationDialogApplyAsync'};
const rows=[],workflows=[];
async function workflow(label,config,steps){const a=setup(config),results=[],states=[];let tx;async function call(step,id){const args=structuredClone(step.args??{});if(args.transactionId==='$transaction')args.transactionId=tx;const controller=new AbortController();a.controller=controller;if(step.abort)controller.abort();const result=await a.host[names[step.tool]](id,args,controller.signal);if(step.tool.endsWith('Preview')){try{tx=JSON.parse(result.result.content[0].text).transactionId}catch{}}return clean(result);}
 for(const step of steps){if(step.patch){change(a.sim.state,step.patch.path,step.patch.value,step.patch.remove);continue;}if(step.status){Object.assign(a.overrides,step.status);continue;}if(step.record){if(tx)Object.assign(a.host.clipLifecycleTransactions.get(tx),step.record);continue;}if('fault'in step){a.fault=step.fault;continue;}
 if(step.concurrent){const offset=results.length;results.push(...await Promise.all(step.concurrent.map((s,i)=>call(s,offset+i+1))));}else results.push(await call(step,results.length+1));states.push(tx?clean(a.host.clipLifecycleTransactions.get(tx)):null);}
 workflows.push({label,config,steps,results,states,calls:a.calls,final:clean({view:a.sim.state.view??null,transport:a.sim.state.playback.transport,locators:a.sim.state.arrangement.locators,dialogRead:a.sim.state.dialogRead,track:a.sim.state.tracks[0]})});}
const apply=(family,key='apply-key',extra={})=>({tool:family+'Apply',args:{transactionId:'$transaction',confirmation:'apply',idempotencyKey:key},...extra});
const defaults={dialogPreview:{button:1},dialogApply:{transactionId:'missing',confirmation:'apply',idempotencyKey:'key'}};
for(const[tool,valid]of Object.entries(defaults)){const cases=[null,[],{},false,0,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const missing={...valid};delete missing[key];cases.push(missing);for(const value of [null,[],{},true,false,-1,0,0.5,1,2,16,17,'','x'])cases.push({...valid,[key]:value});}for(const args of cases){const a=setup();rows.push({tool,args,result:clean(await a.host[names[tool]](1,args))});}}
for(const button of [undefined,0,1,2])for(const scenario of ['normal','expire','epoch','disconnected','operation','message','count','dialogs','incomplete','before','after','cancel','refusal','null','false','no-effect','dialog-read','status','preabort']){
 const config={};if(scenario==='disconnected')config.status={connected:false};if(scenario==='operation')config.status={operations:[]};const steps=[{tool:'dialogPreview',args:button===undefined?{}:{button}}];if(scenario==='expire')steps.push({record:{expiresAt:0}});if(scenario==='epoch')steps.push({status:{epoch:99}});if(scenario==='message')steps.push({patch:{path:['dialogRead','message'],value:'Changed'}});if(scenario==='count')steps.push({patch:{path:['dialogRead','buttonCount'],value:3}});if(scenario==='dialogs')steps.push({patch:{path:['dialogRead','openDialogCount'],value:2}});if(scenario==='incomplete')steps.push({patch:{path:['dialogRead','done'],value:false}});if(['before','after','cancel','refusal','null','false','no-effect','dialog-read','status'].includes(scenario))steps.push({fault:scenario});steps.push(apply('dialog','apply-key',{abort:scenario==='preabort'}),apply('dialog','other-key'),apply('dialog'));await workflow(String(button)+'/'+scenario,config,steps);
}
const baseRead={buttonCount:2,message:'Save?',openDialogCount:1,done:true};const shapes=[null,false,{}, {buttonCount:2,openDialogCount:1},...['buttonCount','message','openDialogCount','done'].flatMap(key=>[null,false,true,0,-1,0.5,1,3,'2',[],{}].map(value=>({...baseRead,[key]:value})))];for(const readOverride of shapes)for(const args of [{},{button:0}])await workflow('read/'+JSON.stringify(args)+'/'+JSON.stringify(readOverride),{readOverride},[{tool:'dialogPreview',args}]);
fs.writeFileSync(new URL('host-dialog-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
